        return "possible"

    if imbalance % 2 != 0:
        return "impossible"

    # Check if we can fix the imbalance with one inversion
    if first_imbalance_index >= 1 and s[first_imbalance_index - 1] == ')':
        return "possible"

    if first_imbalance_index + 1 < n and s[first_imbalance_index + 1] == '(':
